package com.gameaggregator.entitlementservice.domain;import jakarta.persistence.*;import java.time.*;import java.util.UUID;@Entity @Table(name="entitlements") public class Entitlement{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID clientId;@Column(nullable=false)public UUID gameId;@Column(nullable=false)public UUID environmentId;@Column(nullable=false)public String region;@Column(nullable=false)public LocalDate startDate;public LocalDate endDate;@Column(nullable=false)public String status="ACTIVE";public String contractReference;@Version public long version;protected Entitlement(){}public Entitlement(UUID c,UUID g,UUID e,String r,LocalDate s,LocalDate n,String x){clientId=c;gameId=g;environmentId=e;region=r;startDate=s;endDate=n;contractReference=x;}}